using Confluent.Kafka;using Medzo.CatalogueInventory.Application.Common;using Medzo.CatalogueInventory.Infrastructure.Messaging;using Medzo.CatalogueInventory.Infrastructure.Persistence;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Configuration;using Microsoft.Extensions.DependencyInjection;
namespace Medzo.CatalogueInventory.Infrastructure;
public static class DependencyInjection{public static IServiceCollection AddInfrastructure(this IServiceCollection s,IConfiguration c){var cs=c.GetConnectionString("CatalogueInventory")??throw new InvalidOperationException("Set ConnectionStrings__CatalogueInventory.");s.AddDbContext<CatalogueInventoryDbContext>(o=>o.UseMySQL(cs,b=>b.MigrationsAssembly(typeof(CatalogueInventoryDbContext).Assembly.FullName)));s.AddScoped<ICatalogueInventoryStore>(x=>x.GetRequiredService<CatalogueInventoryDbContext>());var brokers=c["Kafka:BootstrapServers"]??"localhost:9092";s.AddSingleton<IProducer<string,string>>(_=>new ProducerBuilder<string,string>(new ProducerConfig{BootstrapServers=brokers,EnableIdempotence=true,Acks=Acks.All}).Build());s.AddHostedService<OutboxPublisher>();s.AddHostedService<StockEventConsumer>();return s;}}

